const input = $json.body ?? $json;

const name = String(input.name ?? '').trim();
const email = String(input.email ?? '').trim().toLowerCase();
const company = String(input.company ?? '').trim();
const interest = String(input.interest ?? '').trim().toLowerCase();
const employees = Number(input.employees ?? 0);

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const errors = [];
if (!name) errors.push('name is required');
if (!email) errors.push('email is required');
else if (!emailValid) errors.push('email is invalid');

if (errors.length) {
  return [{ json: { success: false, errors, receivedAt: new Date().toISOString() } }];
}

return [{ json: { success: true, lead: { name, email, company, interest, employees: Number.isFinite(employees) ? employees : 0 }, receivedAt: new Date().toISOString() } }];

const data = $json;
if (!data.success) return [{ json: data }];

const lead = data.lead;
let score = 0;
if (lead.employees >= 10) score += 20;
if (lead.employees >= 50) score += 20;
if (lead.interest === 'automation') score += 30;
if (lead.interest === 'ai') score += 30;
if (lead.interest === 'integration') score += 25;

const classification = score >= 60 ? 'hot' : score >= 30 ? 'warm' : 'cold';

return [{ json: { success: true, lead: { ...lead, score, classification }, processedAt: new Date().toISOString() } }];
